get_eia_sep &lt;- function(state, abbr) {
  library(tidyverse)
  library(stringr)
  library(httr2)
  library(rvest)
  library(fs)

  state_formatted &lt;- str_to_lower(state) |&gt; str_replace_all("\\s", "")

  dir_name &lt;- fs::path("data", "mp02")
  file_name &lt;- fs::path(dir_name, state_formatted)

  fs::dir_create(dir_name, recurse = TRUE)

  if (!fs::file_exists(file_name)) {
    BASE_URL &lt;- "https://www.eia.gov"
    RESPONSE &lt;- request(BASE_URL) |&gt;
      req_url_path(
        "electricity",
        "state",
        state_formatted
      ) |&gt;
      req_headers(
        `User-Agent` = "Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:149.0) Gecko/20100101 Firefox/149.0"
      ) |&gt;
      req_retry(
        max_tries = 4,
      ) |&gt;
      req_perform(file_name)

    resp_check_status(RESPONSE)
  }

  TABLE &lt;- read_html(file_name) |&gt;
    html_element("table") |&gt;
    html_table() |&gt;
    mutate(Item = str_to_lower(Item))

  if ("U.S. rank" %in% colnames(TABLE)) {
    TABLE &lt;- TABLE |&gt; rename(Rank = `U.S. rank`)
  }

  CO2_MWh &lt;- TABLE |&gt; # nolint: object_name_linter.
    filter(Item == "carbon dioxide (lbs/mwh)") |&gt;
    pull(Value) |&gt;
    str_replace_all(",", "") |&gt;
    as.numeric()

  PRIMARY &lt;- TABLE |&gt;
    filter(Item == "primary energy source") |&gt;
    pull(Rank)

  RATE &lt;- TABLE |&gt;
    filter(Item == "average retail price (cents/kwh)") |&gt;
    pull(Value) |&gt;
    as.numeric()

  GENERATION_MWh &lt;- TABLE |&gt; # nolint: object_name_linter.
    filter(Item == "net generation (megawatthours)") |&gt;
    pull(Value) |&gt;
    str_replace_all(",", "") |&gt;
    as.numeric()

  data.frame(
    CO2_MWh = CO2_MWh,
    primary_source = PRIMARY,
    electricity_price_MWh = RATE * 10, # / 100 cents to dollars &
    # * 1000 kWh to MWH
    generation_MWh = GENERATION_MWh,
    state = state,
    abbreviation = abbr
  )
}

EIA_SEP_REPORT &lt;- map2(state.name, state.abb, get_eia_sep) |&gt; list_rbind()

# Washington, DC is home to WMATA (300M+ annual trips) but is not in
# `state.name`. EIA publishes a DC profile in the same format, so we add it to
# a separate grid table used only for the emissions join. The 50-state
# EIA_SEP_REPORT above is kept as-is for the state-level EDA questions.
GRID_CO2 &lt;- bind_rows(
  EIA_SEP_REPORT,
  get_eia_sep("District of Columbia", "DC")
)


1a: Loaded all the EIA electricity profiles.
The data tells us one page per state from the government’s energy agency. Basically how ‘dirty’ each state’s electricity is and what it costs. This matters because electric trains and buses are only as clean as the power plants that power them (You are only as strong as your weakest link). DC was also added because the metro is huge.


